(function(root){
const copy=x=>JSON.parse(JSON.stringify(x));
function bindings(s){return s.picture_inputs||[{picture:'<Picture 1>',type:'scene',ref_id:s.scene_id},...(s.character_ids||[]).map((id,i)=>({picture:'<Picture '+(i+2)+'>',type:'character',ref_id:id}))];}
function normalize(s,i){if(!s||typeof s!=='object')throw Error('镜头格式错误');const id=s.shot_id||s.id;if(!id)throw Error('镜头缺少 shot_id');const duration=Number(s.duration);if(!Number.isFinite(duration)||duration<=0)throw Error(id+' 时长必须大于0');const out={...copy(s),id,shot_id:id,title:s.title||s.action?.slice(0,18)||id,description:s.action||s.description||'',prompt:s.image_generation?.prompt||s.prompt||'',duration,versions:s.versions||[],pictureSelections:s.pictureSelections||{}};out.picture_inputs=bindings(out);out.picture_inputs.forEach((p,n)=>{if(p.picture!=='<Picture '+(n+1)+'>')throw Error(id+' 图片编号必须连续');if(!['scene','character'].includes(p.type))throw Error(id+' 参考图类型必须是场景或人物');});const chars=out.picture_inputs.filter(p=>p.type==='character').map(p=>p.ref_id);if(JSON.stringify(chars)!==JSON.stringify(s.character_ids||[]))throw Error(id+' 角色图片顺序与 character_ids 不一致');return out;}
function clipPrompt(clip,shots,project){const refs=bindings(clip);const intro=refs.map(p=>{const name=p.type==='scene'?project.scenes?.find(s=>(s.id||s.scene_id)===p.ref_id)?.name:project.characters?.find(c=>(c.id||c.character_id)===p.ref_id)?.name;return p.picture+' 是'+(p.type==='scene'?'场景':'角色')+'参考图'+(name?'（'+name+'）':'')+'。';}).join(' ');let time=0;return intro+' 参考图仅确定外观，不复制多视图排版。\n'+shots.map(s=>{const start=time;time+=s.duration;const dialogue=(s.dialogue||[]).map(d=>{const name=project.characters?.find(c=>(c.id||c.character_id)===d.speaker_id)?.name||'画外声音';return name+'：“'+d.text+'”';}).join('；');return start+'–'+time+'秒：'+s.camera+'。'+s.action+(dialogue?'。对白：'+dialogue:'')}).join('\n')+'\n保持角色、建筑与机械结构一致，雨水和倒影自然运动。';}
function reconcile(project){let t=0;for(const s of project.shots){s.start_time=t;t+=Number(s.duration);s.end_time=t;s.action=s.description;s.image_generation??={};s.image_generation.prompt=s.prompt;}const warnings=[];const clips=project.shotScript?.generation_clips||[];for(const clip of clips){const group=(clip.shot_ids||[]).map(id=>project.shots.find(s=>s.shot_id===id));if(group.some(s=>!s)){warnings.push(clip.clip_id+' 存在缺失镜头');continue;}const indices=group.map(s=>project.shots.indexOf(s));if(group.some(s=>s.scene_id!==clip.scene_id)||indices.some((n,i)=>i&&n!==indices[i-1]+1))warnings.push(clip.clip_id+' 必须由同场景相邻镜头组成');clip.start_time=group[0]?.start_time||0;clip.duration=group.reduce((n,s)=>n+s.duration,0);clip.end_time=clip.start_time+clip.duration;let local=0;clip.timeline=group.map(s=>{const start=local;local+=s.duration;return{shot_id:s.shot_id,start,end:local,camera:s.camera,action:s.action,dialogue:copy(s.dialogue||[])}});if(clip.duration>(project.shotScript.rules?.max_generation_clip_seconds||10))warnings.push(clip.clip_id+' 超过片段时长上限');clip.video_prompt=clipPrompt(clip,group,project);}return{duration:t,warnings};}
function merge(project,raw){if(raw.project_id&&project.project_id&&raw.project_id!==project.project_id)throw Error('project_id 与当前项目不一致');if(!Array.isArray(raw.shots)||!raw.shots.length)throw Error('文件缺少 shots 数组');const incoming=raw.shots.map(normalize),ids=new Set();for(const s of incoming){if(ids.has(s.id))throw Error('重复镜头 '+s.id);ids.add(s.id);}const next=copy(project);next.shots??=[];for(const s of incoming){const i=next.shots.findIndex(p=>(p.shot_id||p.id)===s.id);if(i<0)next.shots.push(s);else{const old=next.shots[i];next.shots[i]={...s,versions:old.versions||[],active:old.active,videoVersions:old.videoVersions||[],videoJob:old.videoJob,activeVideoId:old.activeVideoId,videoResolution:old.videoResolution,firstFrameVersions:old.firstFrameVersions||[],pictureSelections:old.pictureSelections||{}};}}const metadata=copy(raw);delete metadata.shots;metadata.original_generation_clips=copy(raw.generation_clips||[]);for(const clip of metadata.generation_clips||[]){const old=(next.shotScript?.generation_clips||[]).find(c=>c.clip_id===clip.clip_id);if(old)for(const k of ['videoVersions','videoJob','activeVideoId','videoResolution','pictureSelections','custom_video_prompt'])if(old[k]!==undefined)clip[k]=copy(old[k]);}next.shotScript=metadata;const result=reconcile(next);return{project:next,count:incoming.length,...result};}
function pack(project){const out={...copy(project.shotScript||{}),project_id:project.project_id,schema_type:'shot_script',shots:copy(project.shots)};out.actual_duration_seconds=project.shots.reduce((n,s)=>n+s.duration,0);out.summary={shot_count:out.shots.length,clip_count:out.generation_clips?.length||0,duration_seconds:out.actual_duration_seconds};return out;}
const api={merge,normalize,reconcile,pack,bindings};if(typeof module!=='undefined')module.exports=api;else root.ShotSchema=api;
})(typeof window==='undefined'?globalThis:window);
